// Typed arrays
const numbers: number[] = [1, 2, 3, 4, 5];
const doubled: number[] = numbers.map(n => n * 2);
console.log('Doubled:', doubled);

// Tuples
const person: [string, number, boolean] = ['Alice', 30, true];
console.log(`Name: ${person[0]}, Age: ${person[1]}, Active: ${person[2]}`);

// Readonly array
const fruits: readonly string[] = ['apple', 'banana', 'cherry'];
console.log('Fruits:', fruits);
// fruits.push('date'); // Error: Property 'push' does not exist

// Tuple with optional and rest
type Score = [string, number, ...number[]];
const scores: Score = ['Alice', 95, 90, 85, 92];
console.log(`${scores[0]}: ${scores[1]} (all: ${scores.slice(2)})`);

// Array destructuring
const [first, second, ...rest] = [10, 20, 30, 40, 50];
console.log(`First: ${first}, Second: ${second}, Rest: ${rest}`);
